import re, html, json
INDEX = "https://bvirtualogp.pr.gov/ogp/Bvirtual/leyesreferencia/Pages/main_view.aspx"
SEC = re.compile(r"^(?P<kw>Art[íi]culo|ART[ÍI]CULO|Art\.|Secci[óo]n|SECCI[ÓO]N|Secc\.)\s+(?P<id>(?:\d+|[IVXLC]+)(?:\s*[.\-–]\s*(?:\d+|[A-Z]{1,2}(?![a-z])|[IVXLC]+))*(?:-?[A-Z](?![a-zA-Z]))?)\s*\.?\s*[—–\-]+\s*(?P<rest>.*)$")
LPRA = re.compile(r"[\(\[]\s*\d+\s+L\.\s*P\.\s*R\.\s*A\.?[^\(\)\]]{0,80}(?:\([a-z0-9]{1,4}\)[^\)\]]{0,40})?[\)\]]")
STRUCT = re.compile(r"^(CAP[ÍI]TULO|T[ÍI]TULO|SUBCAP[ÍI]TULO|SUBT[ÍI]TULO|PARTE|LIBRO|SECCI[ÓO]N|SUBSECCI[ÓO]N|ART[ÍI]CULO|DISPOSICIONES)\b")
CHROME = re.compile(r"^(Rev\.\s.*|Revisad[oa]\s.*|www\.ogp\.pr\.gov|P[áa]gina\s+\d+\s+de\s+\d+|\{Ir a[^}]*\})$|www\.ogp\.pr\.gov.*P[áa]gina\s+\d+\s+de\s+\d+\s*$")
RUNHEAD = re.compile(r"\[Ley [^\]]{0,90}\]\s*$")
END = re.compile(r"^(Reglamentos y [ÓO]rdenes Ejecutivas|Nota Importante|Notas Importantes|Nota\.\s+Este documento|TABLA DE CONTENIDO)")
OMIT = re.compile(r"^\s*[\[(]?\s*(Omitid[oa]|Derogad[oa]|Reservad[oa]|Enmienda)\b", re.I)

REST = ("https://bvirtualogp.pr.gov/ogp/Bvirtual/leyesreferencia/_api/web/lists/getbytitle('PDF')/items"
        "?$select=FileLeafRef,FileRef,Title,Tipo&$top=5000")

def laws():
    """The library's laws as amended (Tipo 'Ley según enmendada'), from its SharePoint REST feed (Atom). The page's own
    list data is rendered for browsers only; the REST feed answers any client."""
    url, n, seen = REST, 0, set()
    while url:
        kind, feed = fetch(url)
        for e in re.findall(r"<entry\b.*?</entry>", feed, re.S):
            f = lambda k: html.unescape((re.search(r"<d:%s\b[^>/]*>(.*?)</d:%s>" % (k, k), e, re.S) or [None, ""])[1])
            n += 1
            name = re.sub(r"\.pdf$", "", f("FileLeafRef"), flags=re.I)
            m = re.match(r"^0*(\d+)-(\d{4})$", name)
            if not m or not f("Tipo").startswith(("Ley según enmendada", "Plan de Reorganización según enmendado")):
                continue
            key = f"{m.group(1)}-{m.group(2)}"
            if key in seen:
                continue
            seen.add(key)
            yield key, f("Title").strip(), "https://bvirtualogp.pr.gov" + f("FileRef")
        nxt = re.search(r'<link rel="next" href="([^"]+)"', feed)
        url = html.unescape(nxt.group(1)) if nxt else None
    log(f"{n} documents in the OGP reference library, {len(seen)} laws as amended")

def lines_of(text):
    raw = [" ".join(l.split()) for l in html.unescape(text).split("\n")]
    near = {}
    for i, l in enumerate(raw):
        if l.startswith("Rev.") and re.search(r"P[áa]gina\s+\d+", " ".join(raw[i:i + 5])):
            back = [x for x in raw[max(0, i - 6):i] if x][-1:]
            for x in back:
                near[x] = near.get(x, 0) + 1
    running = {x for x, n in near.items() if n >= 2 and not SEC.match(x)}
    out, skip = [], False
    first = next((x for x in raw if x), "")
    for n, l in enumerate(raw):
        if not l or CHROME.search(l) or l in running or (RUNHEAD.search(l) and not SEC.match(l) and len(l) < 300):
            continue
        if l == first and out:
            continue
        if l.startswith("[Nota"):
            skip = not l.rstrip().endswith("]")
            continue
        if skip:
            skip = not l.rstrip().endswith("]")
            continue
        out.append(l)
    return out

def parse(text, title=""):
    nz = lambda x: re.sub(r"[\W_]+", "", x.lower())
    t0 = nz(title)
    ls = [x for x in lines_of(text) if not (t0 and len(x) >= 20 and nz(x) and nz(x) in t0)]   # the running title, wrapped or quoted
    best, cur = {}, None
    i = 0
    while i < len(ls):
        l = ls[i]; i += 1
        m = SEC.match(l)
        roman_struct = m and l == l.upper() and not m.group("id")[0].isdigit()
        if m and not roman_struct:
            kw = "art." if m.group("kw").lower().startswith("art") else "sec."
            rest = m.group("rest").strip()
            if not LPRA.search(rest) and len(rest) < 200:
                for k in (1, 2):
                    nxt = ls[i:i + k]
                    if len(nxt) == k and not any(SEC.match(x) for x in nxt) and LPRA.search(" ".join([rest] + nxt)[:300]):
                        rest = " ".join([rest] + nxt); i += k; break
            lp = LPRA.search(rest)
            dash = re.search(r"\.?\s*[—–]\s+", rest)
            if lp:
                head, after = rest[:lp.start()].strip(" .—–-"), rest[lp.end():].strip(" .—–-")
                head = (head + " " + lp.group(0)).strip()
            elif dash and dash.start() < 80:
                head, after = rest[:dash.start()].strip(" ."), rest[dash.end():]
            elif len(rest) <= 60 and rest.endswith(".") and i < len(ls) and not SEC.match(ls[i]):
                head, after = rest.rstrip(" ."), ""
            else:
                head, after = "", rest
            cur = {"id": re.sub(r"\s+", "", m.group("id")), "kw": kw, "head": head, "body": [after] if after else [], "stop": False}
            best.setdefault((kw, cur["id"]), []).append(cur)
            continue
        if cur is None or cur["stop"]:
            continue
        if END.match(l) or (STRUCT.match(l) and l == l.upper() and len(l) < 160):
            cur["stop"] = True; continue
        cur["body"].append(l)
    for (kw, sid), cands in best.items():
        c = max(cands, key=lambda c: sum(len(x) for x in c["body"]))
        body = "\n".join(c["body"]).strip()
        if not body or (OMIT.match(body) and len(body) < 600) or OMIT.match(c["head"] or "x"):
            continue
        yield kw, sid, c["head"], body

def sections():
    for key, title, url in laws():
        try:
            kind, text = fetch(url)
        except Exception as e:
            log(f"{key}: {e}"); continue
        if kind != "pdf":
            log(f"{key}: not a pdf ({kind}) {url}"); continue
        if len(text) >= 199000:
            log(f"TRUNCATED? Ley {key}: {len(text)} chars (the PDF reader's cap) {url}")
        n = 0
        doc = {"citation": f"Ley {key}", "title": (title or f"Ley {key}")[:300], "doc_type": "statute", "source_url": url}
        for kw, sid, head, body in parse(text, title):
            n += 1
            yield {"id": sid, "heading": head, "text": body, "url": url, "doc": doc, "vars": {"ley": key, "kind": kw}}
        if not n:
            log(f"no articles in Ley {key} {url}")
